const canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d');let mode=0,time=0,rx=.3,ry=.3,zoom=1,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,speed=.6,complexity=.7,color=[255,97,56],drag=null,last=0;const names=['ORBITAL BLOOM','SOFT TERRAIN','STRANGE ATTRACTOR'];
function size(){let r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio,2);canvas.width=r.width*d;canvas.height=r.height*d;ctx.setTransform(d,0,0,d,0,0)}new ResizeObserver(size).observe(canvas);
function project(x,y,z,w,h){let a=ry+time*.12,c=Math.cos(a),s=Math.sin(a),xx=x*c-z*s,zz=x*s+z*c,yy=y*Math.cos(rx)-zz*Math.sin(rx);zz=y*Math.sin(rx)+zz*Math.cos(rx);let scale=Math.min(w,h)*.33*zoom/(1+zz*.17);return [w/2+xx*scale,h/2+yy*scale,zz,scale]}
function render(now){let dt=Math.min((now-last)/1000,.04);last=now;if(!paused&&!drag)time+=dt*speed;let w=canvas.clientWidth,h=canvas.clientHeight;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#85917c14';ctx.lineWidth=1;for(let x=0;x<w;x+=40){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let y=0;y<h;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}
let pts=[],n=Math.floor(60+complexity*100);if(mode===0){for(let j=0;j<46;j++)for(let i=0;i<n;i++){let u=i/n*Math.PI*2,v=j/46*Math.PI*2,twist=v+u*3+Math.sin(time*.4)*.35,r=1.03+.34*Math.cos(twist),x=r*Math.cos(u),z=r*Math.sin(u),y=.34*Math.sin(twist);let ripple=1+.055*Math.sin(v*6+u*5+time);pts.push(project(x*ripple,y*ripple,z*ripple,w,h))}}else if(mode===1){for(let j=0;j<65;j++)for(let i=0;i<n;i++){let x=(i/(n-1)-.5)*3,z=(j/64-.5)*3,y=.26*Math.sin(x*3+time)*Math.cos(z*2+time*.5)+.13*Math.sin(z*5+x*2-time);pts.push(project(x,y,z,w,h))}}else{let x=.1,y=0,z=0;for(let i=0;i<Math.floor(5000+complexity*11000);i++){let dx=10*(y-x),dy=x*(28-z)-y,dz=x*y-8/3*z;x+=dx*.005;y+=dy*.005;z+=dz*.005;if(i%2===0)pts.push(project(x/16,y/20,(z-25)/18,w,h))}}
pts.sort((a,b)=>b[2]-a[2]);for(let p of pts){let alpha=Math.max(.12,Math.min(.95,.58-p[2]*.19));ctx.fillStyle=`rgba(${color},${alpha})`;let r=mode===2?.65:Math.max(.55,1.25+complexity*.45-p[2]*.25);ctx.beginPath();ctx.arc(p[0],p[1],r,0,Math.PI*2);ctx.fill()}requestAnimationFrame(render)}requestAnimationFrame(render);
document.querySelectorAll('.experiment').forEach(b=>b.onclick=()=>{mode=+b.dataset.mode;document.querySelectorAll('.experiment').forEach(e=>{e.classList.toggle('active',e===b);e.setAttribute('aria-pressed',e===b)});document.querySelector('#scene-title').textContent=`0${mode+1} / ${names[mode]}`;rx=mode===1?.65:.3;ry=.3;zoom=1});
for(let id of ['speed','complexity'])document.getElementById(id).oninput=e=>{let v=+e.target.value;if(id==='speed')speed=v;else complexity=v;document.getElementById(id+'-value').textContent=v.toFixed(2)};
document.querySelectorAll('.swatch').forEach(b=>b.onclick=()=>{color=b.dataset.color.split(',').map(Number);document.querySelectorAll('.swatch').forEach(e=>e.classList.toggle('selected',e===b))});
const pause=document.getElementById('pause');function pauseUI(){pause.textContent=paused?'▶':'Ⅱ';pause.setAttribute('aria-label',paused?'Resume animation':'Pause animation')}pauseUI();pause.onclick=()=>{paused=!paused;pauseUI()};document.getElementById('reset').onclick=()=>{rx=mode===1?.65:.3;ry=.3;zoom=1;time=0};canvas.onpointerdown=e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(drag){ry+=(e.clientX-drag[0])*.008;rx+=(e.clientY-drag[1])*.008;drag=[e.clientX,e.clientY]}};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.4,Math.min(2.2,zoom-e.deltaY*.001))},{passive:false});canvas.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','='].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')ry-=.1;if(e.key==='ArrowRight')ry+=.1;if(e.key==='ArrowUp')rx-=.1;if(e.key==='ArrowDown')rx+=.1;if(e.key==='+'||e.key==='=')zoom=Math.min(2.2,zoom+.1);if(e.key==='-')zoom=Math.max(.4,zoom-.1)}};document.getElementById('about').onclick=()=>document.querySelector('dialog').showModal();document.getElementById('close').onclick=()=>document.querySelector('dialog').close();
